"""Assignment 4 driver. Do not edit this file for submission."""

import argparse
import json
import os

import torch
from tqdm import tqdm

from factcheck import (
    LABELS,
    AlwaysRefutedFactChecker,
    EntailmentFactChecker,
    EntailmentModel,
    FactExample,
    RandomGuessFactChecker,
    WordOverlapFactChecker,
)


MODEL_NAME = "MoritzLaurer/DeBERTa-v3-base-mnli-fever-anli"
MODEL_REVISION = "6f5cf0a2b59cabb106aca4c287eed12e357e90eb"


def read_fact_examples(path):
    examples = []
    with open(path, encoding="utf-8") as file:
        for line_no, line in enumerate(file, 1):
            if not line.strip():
                continue
            try:
                item = json.loads(line)
            except json.JSONDecodeError as exc:
                raise ValueError(f"Invalid JSON on line {line_no}: {exc}") from exc
            if not isinstance(item, dict):
                raise ValueError(f"Line {line_no} must be an object")
            claim = item.get("claim")
            label = item.get("label")
            passages = item.get("passages")
            if not isinstance(claim, str) or not claim.strip():
                raise ValueError(f"Line {line_no} has an empty claim")
            if label not in LABELS:
                raise ValueError(f"Line {line_no} has unexpected label {label!r}")
            if not isinstance(passages, list) or not passages or any(not isinstance(p, dict) for p in passages):
                raise ValueError(f"Line {line_no} has invalid passages")
            examples.append(FactExample(claim, passages, label, str(item.get("id", line_no - 1))))
    if not examples:
        raise ValueError("No examples were loaded")
    return examples


def answer_only_passages(passages):
    """Part 1 sees answers and answer types, never gold question wording."""
    return [
        {
            "text": passage.get("answer", passage.get("text", "")),
            "answer": passage.get("answer", ""),
            "answer_type": passage.get("answer_type", ""),
            "boolean_explanation": passage.get("boolean_explanation", ""),
        }
        for passage in passages
    ]


def nli_passages(passages):
    """Expose fixed Q+A evidence without source or internal identifier metadata."""
    return [
        {
            "question": p.get("question", ""),
            "title": p.get("question", p.get("title", "")),
            "answer": p.get("answer", ""),
            "text": p.get("answer", p.get("text", "")),
            "answer_type": p.get("answer_type", ""),
            "boolean_explanation": p.get("boolean_explanation", ""),
        }
        for p in passages
    ]


def evaluate(examples, checker, mode):
    counts = {gold: {pred: 0 for pred in LABELS} for gold in LABELS}
    ent_model = checker.ent_model if mode == "entailment" else None
    for example in tqdm(examples):
        passages = answer_only_passages(example.passages) if mode == "word_overlap" else nli_passages(example.passages)
        if mode == "entailment":
            ent_model.reset_budget()
        prediction = checker.predict(example.fact, passages)
        if mode == "entailment":
            ent_model.assert_budget()
        if prediction not in LABELS:
            raise ValueError(f"FactChecker returned invalid label {prediction!r}")
        counts[example.label][prediction] += 1

    total = len(examples)
    correct = sum(counts[label][label] for label in LABELS)
    print("Confusion matrix (rows=gold, columns=predicted):")
    print("\t" + "\t".join(LABELS))
    for label in LABELS:
        print(label + "\t" + "\t".join(str(counts[label][prediction]) for prediction in LABELS))
    f1s = {}
    for label in LABELS:
        tp = counts[label][label]
        gold_n = sum(counts[label].values())
        pred_n = sum(counts[gold][label] for gold in LABELS)
        f1s[label] = 2 * tp / (gold_n + pred_n) if gold_n + pred_n else 0.0
        print(f"{label} F1: {f1s[label]:.4f}")
    accuracy = correct / total
    macro_f1 = sum(f1s.values()) / len(f1s)
    print(f"Accuracy: {accuracy:.4f}")
    print(f"Macro-F1: {macro_f1:.4f}")
    return {"accuracy": accuracy, "macro_f1": macro_f1, "per_class_f1": f1s}


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--mode", required=True, choices=("random", "always_refuted", "word_overlap", "entailment"))
    parser.add_argument("--data_path", default="data/dev.jsonl")
    parser.add_argument("--model_name", default=MODEL_NAME)
    parser.add_argument("--model_revision", default=MODEL_REVISION)
    parser.add_argument("--max_examples", type=int, default=None, help="Debug only")
    parser.add_argument("--cpu_threads", type=int, default=min(4, os.cpu_count() or 1))
    parser.add_argument("--seed", type=int, default=13)
    args = parser.parse_args()
    if args.max_examples is not None and args.max_examples <= 0:
        parser.error("--max_examples must be positive")
    if args.cpu_threads <= 0:
        parser.error("--cpu_threads must be positive")

    examples = read_fact_examples(args.data_path)
    if args.max_examples is not None:
        examples = examples[:args.max_examples]
    print(f"Evaluating {len(examples)} binary examples")

    if args.mode == "random":
        checker = RandomGuessFactChecker(seed=args.seed)
    elif args.mode == "always_refuted":
        checker = AlwaysRefutedFactChecker()
    elif args.mode == "word_overlap":
        checker = WordOverlapFactChecker()
    else:
        from transformers import AutoModelForSequenceClassification, AutoTokenizer

        torch.set_num_threads(args.cpu_threads)
        tokenizer = AutoTokenizer.from_pretrained(args.model_name, revision=args.model_revision)
        model = AutoModelForSequenceClassification.from_pretrained(args.model_name, revision=args.model_revision)
        checker = EntailmentFactChecker(EntailmentModel(model, tokenizer, max_length=256))
    evaluate(examples, checker, args.mode)


if __name__ == "__main__":
    main()
